changeSet.sql:
INSERT INTO instance_settings (id, silent_mode_engaged)
VALUES (1, TRUE)
ON CONFLICT (id) DO UPDATE
SET silent_mode_engaged = TRUE
WHERE instance_settings.silent_mode_changed_at IS NULL;

ALTER TABLE instance_settings ALTER COLUMN silent_mode_engaged SET DEFAULT TRUE;

rollback.sql:
ALTER TABLE instance_settings ALTER COLUMN silent_mode_engaged DROP DEFAULT;
UPDATE instance_settings SET silent_mode_engaged = FALSE
WHERE id = 1 AND silent_mode_changed_at IS NULL;
